package studio.solocamera;
import java.net.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import org.json.JSONObject;
public final class PreviewBackpressureTest {
 static byte[] packet(String text){return ("\u0001"+text).getBytes(StandardCharsets.UTF_8);}
 static byte[] frame(int index){byte[] data=new byte[4096];ByteBuffer.wrap(data).putInt(index);return data;}
 static void noVideo(Socket socket,SecureChannel channel)throws Exception{socket.setSoTimeout(150);try{byte[] data=channel.receive();if(data[0]==4)throw new AssertionError("Queued frame escaped before acknowledgment");}catch(SocketTimeoutException expected){}finally{socket.setSoTimeout(1500);}}
 public static void main(String[] args)throws Exception{PeerLink.Listener listener=new PeerLink.Listener(){public void approval(String a,java.util.function.Consumer<Boolean> r){r.accept(true);}public void connected(){}public void disconnected(String r){}public void message(JSONObject j){}public void frame(byte[] b){}};try(PeerLink host=new PeerLink(listener)){String key=SecureChannel.newSecret();host.host(key);Thread.sleep(100);try(Socket socket=new Socket("127.0.0.1",PeerLink.PORT);SecureChannel client=SecureChannel.client(socket,key)){if(!new String(client.receive(),StandardCharsets.UTF_8).equals("APPROVED"))throw new AssertionError();client.send(packet("{\"type\":\"previewFlow\",\"version\":1}"));Thread.sleep(100);host.frame(frame(0));byte[] first=client.receive();if(first[0]!=4)throw new AssertionError("Not paced");long firstId=ByteBuffer.wrap(first,1,8).getLong();host.frame(frame(1));byte[] second=client.receive();long secondId=ByteBuffer.wrap(second,1,8).getLong();host.frame(frame(2));client.receive();host.frame(frame(3));client.receive();for(int i=4;i<100;i++)host.frame(frame(i));noVideo(socket,client);host.send(new JSONObject().put("type","control-test"));if(client.receive()[0]!=1)throw new AssertionError("Controls blocked behind video");client.send(packet("{\"type\":\"previewAck\",\"sequence\":"+firstId+"}"));byte[] next=client.receive();if(ByteBuffer.wrap(next,9,4).getInt()!=99)throw new AssertionError("Old frames replayed instead of newest");long nextId=ByteBuffer.wrap(next,1,8).getLong();host.frame(frame(100));client.send(packet("{\"type\":\"previewAck\",\"sequence\":"+firstId+"}"));noVideo(socket,client);client.send(packet("{\"type\":\"previewAck\",\"sequence\":"+secondId+"}"));byte[] last=client.receive();if(ByteBuffer.wrap(last,9,4).getInt()!=100)throw new AssertionError();System.out.println("PASS slow receiver holds at most four frames in transit, skips 95 stale frames, rejects stale ACK, and keeps controls responsive");}}}
}


